22	const BASE_PRICE_BY_TYPE: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	const FIRST_INSURANCE_MULTIPLIER = 1.1;
32	const CONTRACT_FEE = 5;
33	
34	const BUILDING_BLOCK_SIZE = 3;
35	const BUILDING_BLOCK_BASE_PRICE = 60;
36	
37	const allAlike = (items: Item[]): boolean =>
38	  items.every((item) => item.type === items[0].type);
39	
40	const sumOfIndividualPrices = (items: Item[]): number =>
41	  items.reduce((total, item) => total + BASE_PRICE_BY_TYPE[item.type], 0);
42	
43	// Every three alike components form a building block priced at 60 G; the
44	// remainder is priced individually. Only all-alike lists are grouped so far —
45	// mixing types in one list stays unwritten until a test asks.
46	const basePriceOf = (items: Item[]): number => {
47	  if (!allAlike(items)) return sumOfIndividualPrices(items);
48	
49	  const blocks = Math.floor(items.length / BUILDING_BLOCK_SIZE);
50	  const leftovers = items.slice(blocks * BUILDING_BLOCK_SIZE);
51	
52	  return blocks * BUILDING_BLOCK_BASE_PRICE + sumOfIndividualPrices(leftovers);
53	};
54	
55	// Math.round only clears the float artifact in 100 × 1.1 = 110.00000000000001;
56	// no test yet lands on a half-way value, so the rounding *direction* stays
57	// unspecified until the "rounds in MHPCO's favor" test pins it.
58	const quoteStep = (step: Step): StepResult => ({
59	  premium:
60	    Math.round(basePriceOf(step.items!) * FIRST_INSURANCE_MULTIPLIER) + CONTRACT_FEE,
61	});
62	
63	export const runScenario = (scenario: Scenario): ScenarioResult => ({
64	  results: scenario.steps.map(quoteStep),
65	});
